<template>
  <div class="monitor-page">
    <PageHeader title="实时仪表监测" desc="持续轮询已连接的生产数据源，只分析新到数据；发现数据停更、测点冻结或异常突跳时生成告警。" />
    <el-alert type="info" :closable="false" show-icon class="tip">第一版支持已连接的数据源查询（例如 MySQL、TDengine）。查询需返回时间列与测点字段；可使用 <code>{last_timestamp}</code> 仅查询上次检查后的新数据。</el-alert>
    <el-row :gutter="16" class="stats"><el-col :xs="12" :md="6"><el-statistic title="监测任务" :value="monitors.length"/></el-col><el-col :xs="12" :md="6"><el-statistic title="运行中" :value="monitors.filter(x=>x.enabled).length"/></el-col><el-col :xs="12" :md="6"><el-statistic title="活动告警" :value="alerts.filter(x=>x.status==='active').length"/></el-col></el-row>
    <el-card shadow="never"><template #header><div class="header"><span>监测任务</span><div><el-button @click="loadAll">刷新</el-button><el-button type="primary" @click="openCreate">新建实时监测</el-button></div></div></template>
      <el-table :data="monitors" v-loading="loading" stripe empty-text="暂无监测任务">
        <el-table-column prop="name" label="名称" min-width="150"/><el-table-column label="数据源" min-width="150"><template #default="{row}">{{sourceName(row.source_id)}}</template></el-table-column>
        <el-table-column label="测点" min-width="180"><template #default="{row}">{{row.fields.join('、')}}</template></el-table-column><el-table-column label="频率" width="110"><template #default="{row}">{{row.poll_interval_seconds}} 秒</template></el-table-column>
        <el-table-column label="最新数据时间" min-width="170"><template #default="{row}">{{fmt(row.latest_timestamp)}}</template></el-table-column><el-table-column label="状态" width="140"><template #default="{row}"><el-tag :type="row.last_error?'danger':row.enabled?'success':'info'">{{row.last_error?'查询失败':row.enabled?'监测中':'已暂停'}}</el-tag><el-badge v-if="row.active_alerts" :value="row.active_alerts" type="danger" class="badge"/></template></el-table-column>
        <el-table-column label="操作" width="270" fixed="right"><template #default="{row}"><el-button link type="primary" @click="run(row)">立即检查</el-button><el-button link @click="edit(row)">{{row.enabled?'暂停':'恢复'}}</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column>
      </el-table>
    </el-card>
    <el-card shadow="never" class="alerts"><template #header><div class="header"><span>告警记录</span><el-button text @click="loadAlerts">刷新</el-button></div></template><el-table :data="alerts" stripe empty-text="暂无告警"><el-table-column prop="monitor_id" label="监测任务" min-width="160"><template #default="{row}">{{monitorName(row.monitor_id)}}</template></el-table-column><el-table-column prop="field_name" label="测点" min-width="130"><template #default="{row}">{{row.field_name||'-'}}</template></el-table-column><el-table-column label="类型" width="110"><template #default="{row}">{{label(row.alert_type)}}</template></el-table-column><el-table-column prop="message" label="说明" min-width="260"/><el-table-column label="状态" width="95"><template #default="{row}"><el-tag :type="row.status==='active'?'danger':'success'">{{row.status==='active'?'活动':'已恢复'}}</el-tag></template></el-table-column><el-table-column label="最近发生" min-width="175"><template #default="{row}">{{fmt(row.occurred_at)}}</template></el-table-column></el-table></el-card>
    <el-dialog v-model="showDialog" title="新建实时仪表监测" width="650px" destroy-on-close><el-form :model="form" label-width="120px"><el-form-item label="监测名称" required><el-input v-model="form.name" placeholder="例如：传感器在线健康监测"/></el-form-item><el-form-item label="数据源" required><el-select v-model="form.source_id" filterable style="width:100%" placeholder="选择已连接的数据源"><el-option v-for="item in sources" :key="item.id" :label="`${item.name}（${item.type}）`" :value="item.id"/></el-select></el-form-item><el-form-item label="查询语句" required><el-input v-model="form.query_sql" type="textarea" :rows="4" placeholder="SELECT * FROM sensor_table WHERE ts > '{last_timestamp}' ORDER BY ts ASC LIMIT 1000"/><div class="help">仅允许只读查询。首次检查中占位符会替换为 1970-01-01；若数据源不支持该条件，也可先写固定的最近数据查询。</div></el-form-item><el-form-item label="时间列" required><el-input v-model="form.time_column" placeholder="例如 ts 或 timestamp"/></el-form-item><el-form-item label="监测测点" required><el-input v-model="fieldsText" placeholder="多个字段以英文逗号分隔，例如 temperature,pressure"/><div class="help">只填写数值测点；冻结和突跳将分别对每个测点检测。</div></el-form-item><el-row :gutter="12"><el-col :span="12"><el-form-item label="轮询间隔"><el-input-number v-model="form.poll_interval_seconds" :min="15" :max="86400" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="停更告警（秒）"><el-input-number v-model="form.stale_seconds" :min="30" :max="604800" style="width:100%"/></el-form-item></el-col></el-row><el-row :gutter="12"><el-col :span="12"><el-form-item label="冻结点数"><el-input-number v-model="form.freeze_points" :min="3" :max="10000" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="突跳敏感度"><el-input-number v-model="form.jump_sigma" :min="1" :max="20" :step=".5" style="width:100%"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="showDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存并开始监测</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageHeader from '@/components/PageHeader.vue'
import { del, get, post, put } from '@/api/legacy'
const monitors=ref<any[]>([]),alerts=ref<any[]>([]),sources=ref<any[]>([]),loading=ref(false),saving=ref(false),showDialog=ref(false)
const base=()=>({name:'',source_id:'',query_sql:"SELECT * FROM sensor_table WHERE timestamp > '{last_timestamp}' ORDER BY timestamp ASC LIMIT 1000",time_column:'timestamp',poll_interval_seconds:60,stale_seconds:300,freeze_points:20,jump_sigma:6})
const form=ref<any>(base()),fieldsText=ref('')
const sourceMap=computed(()=>new Map(sources.value.map(x=>[x.id,x.name])))
const sourceName=(id:string)=>sourceMap.value.get(id)||id
const monitorName=(id:string)=>monitors.value.find(x=>x.id===id)?.name||id
const label=(v:string)=>({stale:'数据停更',freeze:'测点冻结',jump:'异常突跳'} as any)[v]||v
const fmt=(v:string)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'-'
async function loadAll(){loading.value=true;try{const [m,a,s]:any=await Promise.all([get('/realtime-sensor-monitors'),get('/realtime-sensor-monitors/alerts/list'),get('/datasources')]);monitors.value=m.items||[];alerts.value=a.items||[];sources.value=(s.items||[]).filter((x:any)=>x.status==='connected')}catch(e:any){ElMessage.error(e?.message||'实时监测加载失败')}finally{loading.value=false}}
async function loadAlerts(){try{const a:any=await get('/realtime-sensor-monitors/alerts/list');alerts.value=a.items||[]}catch(e:any){ElMessage.error(e?.message||'告警记录加载失败')}}
function openCreate(){form.value=base();fieldsText.value='';showDialog.value=true}
async function save(){const fields=fieldsText.value.split(',').map(x=>x.trim()).filter(Boolean);if(!form.value.name||!form.value.source_id||!form.value.query_sql||!form.value.time_column||!fields.length)return ElMessage.warning('请完整填写数据源、查询、时间列和监测测点');saving.value=true;try{await post('/realtime-sensor-monitors',{...form.value,fields});showDialog.value=false;ElMessage.success('已开始实时监测；可点击“立即检查”验证连接');await loadAll()}catch(e:any){ElMessage.error(e?.message||'创建失败')}finally{saving.value=false}}
async function run(row:any){try{const r:any=await post(`/realtime-sensor-monitors/${row.id}/run`);ElMessage.success(`检查完成：读取 ${r.new_rows||0} 条新增记录`);await loadAll()}catch(e:any){ElMessage.error(e?.message||'检查失败')}}
async function edit(row:any){try{await put(`/realtime-sensor-monitors/${row.id}`,{enabled:!row.enabled});ElMessage.success(row.enabled?'已暂停':'已恢复');await loadAll()}catch(e:any){ElMessage.error(e?.message||'更新失败')}}
async function remove(row:any){try{await ElMessageBox.confirm(`删除“${row.name}”及其告警记录？`,'确认删除',{type:'warning'});await del(`/realtime-sensor-monitors/${row.id}`);ElMessage.success('已删除');await loadAll()}catch(e:any){if(e!=='cancel')ElMessage.error(e?.message||'删除失败')}}
onMounted(loadAll)
</script>
<style scoped>
.monitor-page{padding:24px}.tip{margin-bottom:16px}.tip code{font-family:monospace}.stats{margin-bottom:16px}.header{display:flex;justify-content:space-between;align-items:center;gap:12px}.alerts{margin-top:16px}.badge{margin-left:8px}.help{font-size:12px;color:#718096;line-height:1.55;margin-top:5px}@media(max-width:768px){.monitor-page{padding:14px}}
</style>
